/**
 * CLN1 conformance.
 *
 * The vectors in vectors.json are generated by an independent Go
 * implementation. Reproducing them byte-for-byte is the only thing that keeps
 * two implementations of a format honest — a round-trip test proves a codec
 * agrees with itself, which is precisely the bug that matters least.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  CLN1_HEADER_SIZE,
  CLN1_GCM_OVERHEAD,
  Cln1StreamDecryptor,
  decrypt,
  encodeHeader,
  encryptWithHeader,
  makeHeader,
  parseHeader,
} from '../src/cln1';
import { bytesToHex } from '../src/bytes';
import { hexToBytes } from './helpers';
import vectors from './vectors.json' with { type: 'json' };

interface Vector {
  name: string;
  key_hex: string;
  header_hex: string;
  plain_hex: string;
  file_hex: string;
  chunk_size: number;
}

const cases = vectors as unknown as Vector[];

test('vectors: encryption reproduces the reference bytes exactly', () => {
  assert.ok(cases.length > 0, 'expected vectors to be present');
  for (const v of cases) {
    const header = parseHeader(hexToBytes(v.header_hex));
    const out = encryptWithHeader(hexToBytes(v.key_hex), header, hexToBytes(v.plain_hex));
    assert.equal(bytesToHex(out), v.file_hex, `vector ${v.name} ciphertext mismatch`);
  }
});

test('vectors: decryption recovers the reference plaintext', () => {
  for (const v of cases) {
    const plain = decrypt(hexToBytes(v.key_hex), hexToBytes(v.file_hex));
    assert.equal(bytesToHex(plain), v.plain_hex, `vector ${v.name} plaintext mismatch`);
  }
});

test('header round-trips through encode/parse', () => {
  const header = makeHeader(1, 7, new Uint8Array(16).fill(9), 4096);
  const parsed = parseHeader(encodeHeader(header));
  assert.deepEqual(parsed, header);
});

test('header rejects a zero key epoch', () => {
  // Epoch 0 is not a valid group key version; accepting it would let a file
  // claim a key that cannot exist.
  const bytes = encodeHeader(makeHeader(1, 1, new Uint8Array(16), 4096));
  new DataView(bytes.buffer).setUint32(12, 0, false);
  assert.throws(() => parseHeader(bytes), /key epoch/);
});

test('the header is authenticated: editing the key epoch breaks decryption', () => {
  // The header is the AAD for every chunk. Without that binding, a server
  // could rewrite key_epoch and point a reader at the wrong key — here it
  // simply fails to authenticate.
  const key = new Uint8Array(32).fill(3);
  const file = encryptWithHeader(key, makeHeader(1, 1, new Uint8Array(16).fill(4), 64), new Uint8Array(200).fill(7));
  new DataView(file.buffer).setUint32(12, 2, false); // key_epoch 1 -> 2
  assert.throws(() => decrypt(key, file), /failed authentication/);
});

test('truncation is detected rather than silently shortening the file', () => {
  // The last-chunk flag lives in the nonce, so a file cut at a chunk boundary
  // cannot be re-read as a shorter but valid file.
  const key = new Uint8Array(32).fill(5);
  const chunkSize = 64;
  const plain = new Uint8Array(200).fill(1);
  const file = encryptWithHeader(key, makeHeader(1, 1, new Uint8Array(16).fill(2), chunkSize), plain);
  const cut = file.subarray(0, CLN1_HEADER_SIZE + (chunkSize + CLN1_GCM_OVERHEAD) * 2);
  assert.throws(() => decrypt(key, cut), /failed authentication/);
});

test('chunks cannot be moved between files', () => {
  // Two files, same key, different nonce prefixes. Splicing a chunk from one
  // into the other must fail: the nonce prefix and the header AAD both differ.
  const key = new Uint8Array(32).fill(6);
  const chunkSize = 64;
  const plain = new Uint8Array(200).fill(8);
  const a = encryptWithHeader(key, makeHeader(1, 1, new Uint8Array(16).fill(1), chunkSize), plain);
  const b = encryptWithHeader(key, makeHeader(1, 1, new Uint8Array(16).fill(2), chunkSize), plain);
  const spliced = new Uint8Array(a);
  spliced.set(b.subarray(CLN1_HEADER_SIZE, CLN1_HEADER_SIZE + chunkSize + CLN1_GCM_OVERHEAD), CLN1_HEADER_SIZE);
  assert.throws(() => decrypt(key, spliced), /failed authentication/);
});

test('streaming decryption matches whole-file decryption, at any feed size', () => {
  const key = new Uint8Array(32).fill(11);
  const chunkSize = 64;
  const plain = new Uint8Array(500);
  for (let i = 0; i < plain.length; i++) plain[i] = i & 0xff;
  const file = encryptWithHeader(key, makeHeader(1, 1, new Uint8Array(16).fill(12), chunkSize), plain);

  for (const feed of [1, 7, 33, chunkSize + CLN1_GCM_OVERHEAD, file.length]) {
    const dec = new Cln1StreamDecryptor(key);
    const parts: Uint8Array[] = [];
    for (let i = 0; i < file.length; i += feed) {
      parts.push(...dec.push(file.subarray(i, Math.min(i + feed, file.length))));
    }
    parts.push(dec.finish());
    const joined = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
    let off = 0;
    for (const p of parts) {
      joined.set(p, off);
      off += p.length;
    }
    assert.deepEqual(joined, plain, `feed size ${feed}`);
  }
});

test('a stream cut short throws instead of returning a partial file', () => {
  const key = new Uint8Array(32).fill(13);
  const chunkSize = 64;
  const file = encryptWithHeader(key, makeHeader(1, 1, new Uint8Array(16).fill(14), chunkSize), new Uint8Array(200).fill(2));
  const dec = new Cln1StreamDecryptor(key);
  dec.push(file.subarray(0, CLN1_HEADER_SIZE + chunkSize + CLN1_GCM_OVERHEAD + 5));
  assert.throws(() => dec.finish(), /failed authentication|truncated/);
});

test('an empty file still authenticates', () => {
  // Zero-length input must produce one authenticated chunk, not zero chunks:
  // a file with no chunks would be indistinguishable from a deleted one.
  const key = new Uint8Array(32).fill(15);
  const file = encryptWithHeader(key, makeHeader(1, 1, new Uint8Array(16).fill(16), 1024), new Uint8Array(0));
  assert.equal(file.length, CLN1_HEADER_SIZE + CLN1_GCM_OVERHEAD);
  assert.equal(decrypt(key, file).length, 0);
});
